import fs from 'node:fs/promises';import vm from 'node:vm';const root=new URL('../',import.meta.url),read=p=>fs.readFile(new URL(p,root),'utf8');let base=await read('shared/review-hub-before-vibe.html');base=base.replace('Design room — Someone.lawyer & AI Company Market','Vibe Coding Design Tool').replace('Design room<span','Vibe Coding<span').replace('/ 01</span>',' / DESIGN TOOL</span>').replace('Interactive review','Draft workspace').replace('Someone.lawyer × AI Company Market','VIBE CODING / DESIGN WORKSPACE').replace('Find the right direction.','Design it. Refine it. Build it.').replace('Two complete brand files. Five designs each. Switch, explore and compare every page.','Explore fourteen directions. Tune the system. Turn your decisions into a clear build brief.');const css=(await read('shared/fonts-embedded.css'))+'\n'+await read('shared/vibe-tool.css'),js=await read('shared/vibe-tool.js');base=base.replace('</head>','<style>'+css+'</style></head>');base=base.replace('</body>',()=>'<script>'+js.replaceAll('</script','<\/script')+'</script></body>');for(const m of base.matchAll(/<script>([\s\S]*?)<\/script>/g))new vm.Script(m[1]);await fs.writeFile(new URL('shared/review-hub.html',root),base);await fs.writeFile(new URL('design-studio.html',root),base);console.log('Vibe Coding Design Tool rebuilt; scripts compile.');